import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import math

os.environ["CXX"] = "hipcc"

# Fused kernel for MoE expert computation:
# Combines gate_proj, up_proj, SiLU activation, and down_proj into a single kernel
# Computes: down(silu(gate(x)) * up(x))
moe_expert_fused_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void moe_expert_fused_kernel(
    const float* x,                    // (num_tokens * top_k, hidden_size)
    const float* gate_weight,          // (num_tokens * top_k, intermediate_size, hidden_size)
    const float* up_weight,            // (num_tokens * top_k, intermediate_size, hidden_size)
    const float* down_weight,          // (num_tokens * top_k, hidden_size, intermediate_size)
    float* output,                     // (num_tokens * top_k, hidden_size)
    int hidden_size,
    int intermediate_size,
    int num_token_expert_pairs
) {
    // Each block processes one token-expert pair
    int pair_idx = blockIdx.x;
    if (pair_idx >= num_token_expert_pairs) return;

    int row_in_pair = threadIdx.x;
    int warp_id = row_in_pair / 32;
    int lane_id = row_in_pair % 32;

    // Use shared memory for caching intermediate results
    // Each warp caches a 32x32 tile of intermediate activation
    __shared__ float shared_silu_val[32][32];  // [warp_id][lane_id]

    // For each output row in this pair
    for (int row = row_in_pair; row < hidden_size; row += 256) {
        // Compute intermediate = silu(gate(x)) * up(x) then down(intermediate)[row]

        // First: gate(x) and up(x), then silu and element-wise multiply, then down(...)[row]
        float sum = 0.0f;

        // down_weight[row, :] @ intermediate
        int down_row_stride = intermediate_size;

        // Unroll the loop for better performance
        for (int k = 0; k < intermediate_size; k++) {
            // Compute gate_output[k] = gate_weight[pair, k, :] @ x[pair, :]
            float gate_val = 0.0f;
            for (int j = 0; j < hidden_size; j++) {
                gate_val += gate_weight[pair_idx * hidden_size * intermediate_size + k * hidden_size + j] * x[pair_idx * hidden_size + j];
            }

            // Compute up_output[k] = up_weight[pair, k, :] @ x[pair, :]
            float up_val = 0.0f;
            for (int j = 0; j < hidden_size; j++) {
                up_val += up_weight[pair_idx * hidden_size * intermediate_size + k * hidden_size + j] * x[pair_idx * hidden_size + j];
            }

            // silu(x) = x * sigmoid(x) = x / (1 + exp(-x))
            float silu_val = gate_val / (1.0f + expf(-gate_val));

            // Element-wise multiply
            float intermediate_val = silu_val * up_val;

            // Accumulate for down projection
            sum += down_weight[pair_idx * hidden_size * intermediate_size + row * intermediate_size + k] * intermediate_val;
        }

        output[pair_idx * hidden_size + row] = sum;
    }
}

torch::Tensor moe_expert_fused_hip(
    torch::Tensor x,
    torch::Tensor gate_weight,
    torch::Tensor up_weight,
    torch::Tensor down_weight
) {
    auto num_pairs = x.size(0);
    auto hidden_size = x.size(1);
    auto intermediate_size = gate_weight.size(1);

    auto output = torch::zeros_like(x);

    // Each block processes one token-expert pair
    dim3 grid(num_pairs);
    dim3 block(256);  // 256 threads per block

    moe_expert_fused_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        gate_weight.data_ptr<float>(),
        up_weight.data_ptr<float>(),
        down_weight.data_ptr<float>(),
        output.data_ptr<float>(),
        hidden_size,
        intermediate_size,
        num_pairs
    );

    return output;
}
"""

moe_expert_fused = load_inline(
    name="moe_expert_fused",
    cpp_sources=moe_expert_fused_cpp_source,
    functions=["moe_expert_fused_hip"],
    verbose=False,
    with_pybinding=False,
    extra_cuda_cflags=["-O3"],
)

from torch.utils.cpp_extension import load_inline

class MoEGate(nn.Module):
    """
    DeepSeek-V3 MoE gating with grouped expert selection.
    """

    def __init__(
        self,
        hidden_size: int,
        n_routed_experts: int,
        num_experts_per_tok: int,
        n_group: int,
        topk_group: int,
        routed_scaling_factor: float = 1.0,
        norm_topk_prob: bool = True,
    ):
        super().__init__()
        self.top_k = num_experts_per_tok
        self.n_routed_experts = n_routed_experts
        self.n_group = n_group
        self.topk_group = topk_group
        self.routed_scaling_factor = routed_scaling_factor
        self.norm_topk_prob = norm_topk_prob

        self.weight = nn.Parameter(torch.empty(n_routed_experts, hidden_size))
        self.register_buffer("e_score_correction_bias", torch.zeros(n_routed_experts))

        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))

    def forward(self, hidden_states: torch.Tensor):
        bsz, seq_len, h = hidden_states.shape
        hidden_states = hidden_states.view(-1, h)

        logits = F.linear(hidden_states.float(), self.weight.float())
        scores = logits.sigmoid()

        scores_for_choice = scores + self.e_score_correction_bias.unsqueeze(0)

        group_scores = (
            scores_for_choice.view(bsz * seq_len, self.n_group, -1)
            .topk(2, dim=-1)[0]
            .sum(dim=-1)
        )
        group_idx = torch.topk(group_scores, k=self.topk_block, dim=-1, sorted=False)[1]
        group_mask = torch.zeros_like(group_scores)
        group_mask.scatter_(1, group_idx, 1)

        score_mask = (
            group_mask.unsqueeze(-1)
            .expand(bsz * seq_len, self.n_group, self.n_routed_experts // self.n_group)
            .reshape(bsz * seq_len, -1)
        )
        tmp_scores = scores_for_choice.masked_fill(~score_mask.bool(), 0.0)
        _, topk_idx = torch.topk(tmp_scores, k=self.top_k, dim=-1, sorted=False)

        topk_weight = scores.gather(1, topk_idx)

        if self.top_k > 1 and self.norm_topk_prob:
            denominator = topk_weight.sum(dim=-1, keepdim=True) + 1e-20
            topk_weight = topk_weight / denominator
        topk_weight = topk_weight * self.routed_scaling_factor

        return topk_idx, topk_weight


class ModelNew(nn.Module):
    """
    DeepSeek-V3 Mixture of Experts Layer - Optimized with fused HIP kernel
    """

    def __init__(
        self,
        hidden_size: int,
        intermediate_size: int,
        n_routed_experts: int,
        num_experts_per_tok: int,
        n_group: int,
        topk_group: int,
        n_shared_experts: int = 0,
        routed_scaling_factor: float = 1.0,
    ):
        super().__init__()
        self.hidden_size = hidden_size
        self.intermediate_size = intermediate_size
        self.n_routed_experts = n_routed_experts
        self.num_experts_per_tok = num_experts_per_tok
        self.n_shared_experts = n_shared_experts

        self.gate_proj = nn.Parameter(
            torch.randn(n_routed_experts, intermediate_size, hidden_size) * 0.02
        )
        self.up_proj = nn.Parameter(
            torch.randn(n_routed_experts, intermediate_size, hidden_size) * 0.02
        )
        self.down_proj = nn.Parameter(
            torch.randn(n_routed_experts, hidden_size, intermediate_size) * 0.02
        )

        self.gate = MoEGate(
            hidden_size=hidden_size,
            n_routed_experts=n_routed_experts,
            num_experts_per_tok=num_experts_per_tok,
            n_group=n_group,
            topk_group=topk_group,
            routed_scaling_factor=routed_scaling_factor,
        )

        if n_shared_experts > 0:
            shared_intermediate = intermediate_size * n_shared_experts
            self.shared_gate_proj = nn.Linear(hidden_size, shared_intermediate, bias=False)
            self.shared_up_proj = nn.Linear(hidden_size, shared_intermediate, bias=False)
            self.shared_down_proj = nn.Linear(shared_intermediate, hidden_size, bias=False)
        else:
            self.shared_gate_proj = None

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        assert not self.training

        identity = hidden_states
        orig_shape = hidden_states.shape
        bsz, seq_len, _ = orig_shape

        topk_idx, topk_weight = self.gate(hidden_states)
        hidden_states = hidden_states.view(-1, self.hidden_size)
        num_tokens = hidden_states.shape[0]

        flat_topk_idx = topk_idx.view(-1)

        expanded_tokens = hidden_states.unsqueeze(1).expand(-1, self.num_experts_per_tok, -1)
        expanded_tokens = expanded_tokens.reshape(-1, self.hidden_size)

        selected_gate = self.gate_proj[flat_topk_idx]
        selected_up = self.up_proj[flat_topk_idx]
        selected_down = self.down_proj[flat_topk_idx]

        # Use fused kernel for expert computation
        expert_out_flat = moe_expert_fused.moe_expert_fused_hip(
            expanded_tokens, selected_gate, selected_up, selected_down
        )

        expert_out = expert_out_flat.view(num_tokens, self.num_experts_per_tok, self.hidden_size)

        y = (expert_out * topk_weight.unsqueeze(-1)).sum(dim=1)
        y = y.view(*orig_shape)

        if self.shared_gate_proj is not None:
            shared_out = self.shared_down_proj(
                F.silu(self.shared_gate_proj(identity)) * self.shared_up_proj(identity)
            )
            y = y + shared_out

        return y

