# Fused kernel for MoE expert computation:
# Combines gate_proj, up_proj, SiLU activation, and down_proj into a single kernel
# Computes: down(silu(gate(x)) * up(x))
moe_expert_fused_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void moe_expert_fused_kernel(
    const float* x,                    // (num_tokens * top_k, hidden_size)
    const float* gate_weight,          // (num_tokens * top_k, intermediate_size, hidden_size)
    const float* up_weight,            // (num_tokens * top_k, intermediate_size, hidden_size)
    const float* down_weight,          // (num_tokens * top_k, hidden_size, intermediate_size)
    float* output,                     // (num_tokens * top_k, hidden_size)
    int hidden_size,
    int intermediate_size,
    int num_token_expert_pairs
) {
    // Each block processes one token-expert pair
    int pair_idx = blockIdx.x;
    if (pair_idx >= num_token_expert_pairs) return;

    int row_in_pair = threadIdx.x;

    // For each output row in this pair
    for (int row = row_in_pair; row < hidden_size; row += 256) {
        // Compute intermediate = silu(gate(x)) * up(x) then down(intermediate)[row]
        float sum = 0.0f;

        // down_weight[row, :] @ intermediate
        int down_row_stride = intermediate_size;

        // Unroll the loop for better performance
        for (int k = 0; k < intermediate_size; k++) {
            // Compute gate_output[k] = gate_weight[pair, k, :] @ x[pair, :]
            float gate_val = 0.0f;
            for (int j = 0; j < hidden_size; j++) {
                gate_val += gate_weight[pair_idx * hidden_size * intermediate_size + k * hidden_size + j] * x[pair_idx * hidden_size + j];
            }

            // Compute up_output[k] = up_weight[pair, k, :] @ x[pair, :]
            float up_val = 0.0f;
            for (int j = 0; j < hidden_size; j++) {
                up_val += up_weight[pair_idx * hidden_size * intermediate_size + k * hidden_size + j] * x[pair_idx * hidden_size + j];
            }

            // silu(x) = x * sigmoid(x) = x / (1 + exp(-x))
            float silu_val = gate_val / (1.0f + expf(-gate_val));

            // Element-wise multiply
            float intermediate_val = silu_val * up_val;

            // Accumulate for down projection
            sum += down_weight[pair_idx * hidden_size * intermediate_size + row * intermediate_size + k] * intermediate_val;
        }

        output[pair_idx * hidden_size + row] = sum;
    }
}

torch::Tensor moe_expert_fused_hip(
    torch::Tensor x,
    torch::Tensor gate_weight,
    torch::Tensor up_weight,
    torch::Tensor down_weight
) {
    auto num_pairs = x.size(0);
    auto hidden_size = x.size(1);
    auto intermediate_size = gate_weight.size(1);

    auto output = torch::zeros_like(x);

    // Each block processes one token-expert pair
    dim3 grid(num_pairs);
    dim3 block(256);  // 256 threads per block

    moe_expert_fused_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        gate_weight.data_ptr<float>(),
        up_weight.data_ptr<float>(),
        down_weight.data_ptr<float>(),
        output.data_ptr<float>(),
        hidden_size,
        intermediate_size,
        num_pairs
    );

    return output;
}
