import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import math

os.environ["CXX"] = "hipcc"

from torch.utils.cpp_extension import load_inline

# Fused kernel for MoE expert computation that works with stacked weights
# Avoids creating large intermediate tensors by computing everything in-place
# Computes: down(silu(gate(x)) * up(x)) using grouped expert weights
moe_expert_fused_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void moe_expert_fused_kernel(
    const float* hidden_states,       // (num_tokens, hidden_size)
    const int64_t* topk_idx,         // (num_tokens, top_k) expert indices
    const float* gate_weight,         // (n_experts, intermediate, hidden)
    const float* up_weight,           // (n_experts, intermediate, hidden)
    const float* down_weight,         // (n_experts, hidden, intermediate)
    const float* topk_weight,         // (num_tokens, top_k)
    float* output,                    // (num_tokens, hidden_size)
    int num_tokens,
    int top_k,
    int hidden_size,
    int intermediate_size,
    int n_experts
) {
    // Each thread block processes one token
    int token = blockIdx.x;
    if (token >= num_tokens) return;

    int hidden_row = threadIdx.x;

    // Shared memory for accumulating this token's output
    extern __shared__ float token_output[];
    token_output[hidden_row] = 0.0f;

    // Process each expert for this token
    for (int k_idx = 0; k_idx < top_k; k_idx++) {
        int expert_idx = topk_idx[token * top_k + k_idx];
        float weight = topk_weight[token * top_k + k_idx];

        // Use this expert's weight
        const float* this_gate = gate_weight + expert_idx * intermediate_size * hidden_size;
        const float* this_up = up_weight + expert_idx * intermediate_size * hidden_size;
        const float* this_down = down_weight + expert_idx * hidden_size * intermediate_size;

        const float* x = hidden_states + token * hidden_size;

        // Compute contribution to output:
        // output_col = weight * (down_col_col2 * silu(gate_col2 * x) * (up_col2 * x))
        // = weight * sum_down_col (down_col_col2 * silu(gate_col2 * x) * up_col2 * x)

        float local_sum = 0.0f;

        // Compute for each hidden output dimension (one per thread)
        // Loop over intermediate dimension
        for (int inter = 0; inter < intermediate_size; inter++) {
            // Compute gate_output[inter] = gate[inter, :] @ x
            float gate_val = 0.0f;
            for (int j = 0; j < hidden_size; j++) {
                gate_val += this_gate[inter * hidden_size + j] * x[j];
            }

            // Compute up_output[inter] = up[inter, :] @ x
            float up_val = 0.0f;
            for (int j = 0; j < hidden_size; j++) {
                up_val += this_up[inter * hidden_size + j] * x[j];
            }

            // SiLU activation
            float silu_val = gate_val / (1.0f + expf(-gate_val));

            // Element-wise multiply
            float intermediate_val = silu_val * up_val;

            // Down projection for this hidden dimension
            local_sum += this_down[hidden_row * intermediate_size + inter] * intermediate_val;
        }

        token_output[hidden_row] += weight * local_sum;
    }

    // Write output
    output[token * hidden_size + hidden_row] = token_output[hidden_row];
}

torch::Tensor moe_expert_fused_hip(
    torch::Tensor hidden_states,
    torch::Tensor topk_idx,
    torch::Tensor gate_weight,
    torch::Tensor up_weight,
    torch::Tensor down_weight,
    torch::Tensor topk_weight
) {
    auto num_tokens = hidden_states.size(0);
    auto hidden_size = hidden_states.size(1);
    auto top_k = topk_idx.size(1);
    auto intermediate_size = gate_weight.size(1);
    auto n_experts = gate_weight.size(0);

    auto output = torch::zeros_like(hidden_states);

    dim3 grid(num_tokens);
    dim3 block(hidden_size);
    int shared_mem = hidden_size * sizeof(float);

    // Make sure hidden_size is a power of 2 and <= 1024
    moe_expert_fused_kernel<<<grid, block, shared_mem>>>(
        hidden_states.data_ptr<float>(),
        topk_idx.data_ptr<int64_t>(),
        gate_weight.data_ptr<float>(),
        up_weight.data_ptr<float>(),
        down_weight.data_ptr<float>(),
        topk_weight.data_ptr<float>(),
        output.data_ptr<float>(),
        num_tokens,
        top_k,
        hidden_size,
        intermediate_size,
        n_experts
    );

    return output;
}
"""

